2. Create a `model.ts` file in your project directory:

```typescript
import { Model, Schema } from 'mongoose';

export interface IUser extends Document {
  name: string;
  age: number;
}

export interface IAddress extends Document {
  street: string;
  city: string;
  state: string;
}

const userSchema = new Schema({
  name: String,
  age: Number,
});

const addressSchema = new Schema({
  street: String,
  city: String,
  state: String,
});

const UserModel: Model<IUser> = model('User', userSchema);
const AddressModel: Model<IAddress> = model('Address', addressSchema);

export { UserModel, AddressModel };
```

3. In your `app.module.ts` file, import the necessary modules and register the `Model` classes:

```typescript
import { Module } from '@nestjs/common';
import { MongoClientModule } from '@nestjs/mongodb';
import { UserModel, AddressModel } from './models/model';

@Module({
  imports: [
    MongoClientModule.forRoot('mongodb://localhost/mydatabase'),
  ],
  controllers: [],
  providers: [
    { provide: 'UserModel', useValue: UserModel },
    { provide: 'AddressModel', useValue: AddressModel },
  ],
})
export class AppModule {}
```

Now you have a NestJS model that creates a MongoDB document containing multiple schemas. You can use these models in your controllers and services to interact with the database.

