Here's a Go program that parses a struct in a Go source file and generates a Avro schema from it:

```go
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"strings"

	"github.com/apache/avro/avro"
	"github.com/apache/avro/avro/schema"
)

func main() {
	filePath := "path/to/your/go/source/file.go"
	structName := "YourStructName"

	content, err := ioutil.ReadFile(filePath)
	if err != nil {
		log.Fatal(err)
	}

	var structDefinition strings.Builder
	for _, line := range strings.Split(string(content), "\n") {
		if strings.HasPrefix(line, fmt.Sprintf("type %s struct ", structName)) {
			structDefinition.WriteString(line)
			break
		}
	}

	if structDefinition.Len() == 0 {
		log.Fatalf("Unable to find struct definition for %s in %s", structName, filePath)
	}

	var avroSchema *schema.Schema
	err = json.Unmarshal([]byte(structDefinition.String()), &avroSchema)
	if err != nil {
		log.Fatal(err)
	}

	outputFile := fmt.Sprintf("%s.avsc", structName)
	err = ioutil.WriteFile(outputFile, avroSchema.JSON(), 0644)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("Avro schema generated and written to %s\n", outputFile)
}
```

Replace `"path/to/your/go/source/file.go"` with the path to your Go source file and `"YourStructName"` with the name of the struct you want to convert. The program will generate an Avro schema file named `struct.avsc` in the same directory as the Go source file.

