To create a simple toast notification using React Context, follow these steps:

1. Create a `ToastContext` file:

```javascript
import { createContext, useState } from 'react';

export const ToastContext = createContext(null);

function ToastProvider({ children }) {
  const [toast, setToast] = useState(null);

  function showToast(message, duration) {
    setToast({ message, duration });

    setTimeout(() => {
      setToast(null);
    }, duration);
  }

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
    </ToastContext.Provider>
  );
}

export default ToastProvider;
```

2. Create a `Toast` component:

```javascript
import React from 'react';
import { useContext } from 'react';

function Toast() {
  const { toast } = useContext(ToastContext);

  if (!toast) {
    return null;
  }

  return (
    <div className="toast">
      {toast.message}
    </div>
  );
}

export default Toast;
```

3. Use the `ToastProvider` and `Toast` components in your app:

```javascript
import React from 'react';
import { ToastProvider, Toast } from './ToastContext';

function App() {
  return (
    <ToastProvider>
      <Toast />
      <button onClick={() => showToast('This is a toast!', 3000)}>Show Toast</button>
    </ToastProvider>
  );
}

export default App;
```

Now you have a simple toast notification system using React Context. You can customize the toast's style and behavior as needed.

