Here's an example of how you can display the set of prime numbers (3, 7, 13, and 19) in an organized manner on a webpage using HTML and JavaScript. The JavaScript function will calculate their product.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Prime Numbers</title>
    <style>
        .prime-numbers {
            display: flex;
            flex-wrap: wrap;
            justify-content: space-between;
        }

        .prime-number {
            width: calc(33.33% - 10px);
            margin-bottom: 10px;
            text-align: center;
        }
    </style>
</head>
<body>
    <div class="prime-numbers">
        <div class="prime-number">3</div>
        <div class="prime-number">7</div>
        <div class="prime-number">13</div>
        <div class="prime-number">19</div>
    </div>

    <script>
        function calculateProduct() {
            const primeNumbers = [3, 7, 13, 19];
            let product = 1;

            for (let i = 0; i < primeNumbers.length; i++) {
                product *= primeNumbers[i];
            }

            return product;
        }

        const productElement = document.createElement('p');
        productElement.textContent = `The product of the prime numbers is ${calculateProduct()}.`;

        document.body.appendChild(productElement);
    </script>
</body>
</html>
```

