Here's a simple TypeScript program that generates a bar chart from a user-inputted dataset using the Chart.js library:

```typescript
import * as Chart from 'chart.js';

interface Dataset {
  label: string;
  data: number[];
}

function generateBarChart(datasets: Dataset[]): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  const chartData = {
    labels: datasets.map(dataset => dataset.label),
    datasets: datasets.map(dataset => ({
      label: dataset.label,
      data: dataset.data,
      backgroundColor: [
        'rgba(255, 99, 132, 0.2)',
        'rgba(54, 162, 235, 0.2)',
        'rgba(255, 206, 86, 0.2)'
      ],
      borderColor: [
        'rgba(255, 99, 132, 1)',
        'rgba(54, 162, 235, 1)',
        'rgba(255, 206, 86, 1)'
      ],
      borderWidth: 1
    }))
  };

  const chartOptions = {
    scales: {
      y: {
        beginAtZero: true
      }
    }
  };

  new Chart(ctx, {
    type: 'bar',
    data: chartData,
    options: chartOptions
  });

  return canvas;
}

// Example usage
const datasets: Dataset[] = [
  { label: 'Dataset 1', data: [1, 2, 3] },
  { label: 'Dataset 2', data: [4, 5, 6] },
  { label: 'Dataset 3', data: [7, 8, 9] }
];

const chart = generateBarChart(datasets);
document.body.appendChild(chart);
```

