Here's a PowerShell script that recursively checks folders for ACLs referring to SIDs in the SIDHistory of users or groups in the domain:

```powershell
# Define the domain name and path to the folder to start the search from
$domain = "your_domain_name"
$startPath = "C:\path\to\start\folder"

# Function to check if an ACL refers to a SID in the SIDHistory of a user or group
function CheckACL($acl, $sidHistory) {
    foreach ($access in $acl.Access) {
        $sid = $access.Sid
        if ($sidHistory.Contains($sid)) {
            return $true
        }
    }
    return $false
}

# Function to recursively check folders for ACLs with SIDs in the SIDHistory
function CheckFolders($path, $sidHistory) {
    Get-ChildItem -Path $path -Directory | ForEach-Object {
        $acl = (Get-Acl -Path $_.FullName).Access
        if (CheckACL($acl, $sidHistory)) {
            Write-Host "Folder: $($_.FullName) - ACL refers to a SID in the SIDHistory"
        }
        CheckFolders($_.FullName, $sidHistory)
    }
}

# Get the SIDHistory of all users and groups in the domain
$sidHistory = (Get-ADUser -Filter {(objectCategory -eq "person")} -Properties *).SIDHistory

# Check the starting folder for ACLs with SIDs in the SIDHistory
CheckFolders($startPath, $sidHistory)
```

Replace `your_domain_name` with your actual domain name and `C:\path\to\start\folder` with the path to the folder you want to start the search from. This script will recursively check all folders in the specified path and its subfolders for ACLs with SIDs in the SIDHistory.
